/**
 * Фасад сессии для macOS shell.
 */
public protocol MeetingCoreProtocol: AnyObject, Sendable {
    
    func apiBaseUrl()  -> String
    
    /**
     * Пересобрать финальный транскрипт из сохранённых captions.
     */
    func assembleFinalNow(meetingId: String)  -> String
    
    /**
     * Число сохранённых live captions.
     */
    func captionEventCount(sessionId: String)  -> UInt64
    
    /**
     * Ответ host bridge → в translation stream.
     */
    func completeHostTranslation(id: String, translatedText: String)  -> String
    
    func deleteGlossaryTerm(id: String)  -> String
    
    /**
     * Удалить ручную метку спикера.
     */
    func deleteSpeaker(id: String)  -> String
    
    /**
     * Demo script events (не STT).
     */
    func drainEvents()  -> [FfiCaptionEvent]
    
    func drainHostTranslationRequests()  -> [FfiHostTranslationRequest]
    
    /**
     * Live STT captions, накопленные после ingest.
     */
    func drainLiveCaptions()  -> [FfiCaptionEvent]
    
    /**
     * Отдельный поток sync-перевода (demo + live); пусто если выключен.
     */
    func drainLiveTranslations()  -> [FfiCaptionEvent]
    
    /**
     * Фактический backend после резолва `auto` (для UI/debug).
     */
    func effectiveTranslationBackend()  -> String
    
    /**
     * Сгенерировать и сохранить локальный артефакт из final transcript.
     */
    func generateArtifact(meetingId: String, kind: FfiArtifactKind)  -> FfiGenerateArtifactResult
    
    func getBackendArtifact(artifactId: String)  -> FfiBackendArtifact
    
    func getBackendJob(jobId: String)  -> FfiBackendJob
    
    /**
     * Последний финальный транскрипт или пустой DTO.
     */
    func getFinalTranscript(meetingId: String)  -> FfiFinalTranscript
    
    func importGlossaryCsv(csv: String)  -> FfiGlossaryImportResult
    
    func ingestAudioChunk(channel: FfiAudioChannel, pcm: Data, sampleRate: UInt32, timestampMs: UInt64)  -> String
    
    /**
     * Сохранённые post-call артефакты выбранной встречи.
     */
    func listArtifacts(meetingId: String)  -> [FfiArtifact]
    
    /**
     * Сохранённые live captions выбранной встречи.
     */
    func listCaptions(meetingId: String)  -> [FfiCaptionEvent]
    
    func listGlossaryTerms()  -> [FfiGlossaryTerm]
    
    /**
     * Встречи, доступные в локальной истории.
     */
    func listMeetings()  -> [FfiMeetingSummary]
    
    /**
     * Спикеры встречи в пользовательском порядке.
     */
    func listSpeakers(meetingId: String)  -> [FfiSpeaker]
    
    func liveTranslationTarget()  -> String
    
    func manifestChunkCount(sessionId: String)  -> UInt64
    
    /**
     * Каталог моделей: `{data_root}/models`.
     */
    func modelsDirectory()  -> String
    
    func sessionLanguage()  -> String
    
    /**
     * ADR-007: base URL + bearer token (в памяти процесса).
     */
    func setApiConfig(baseUrl: String, token: String) 
    
    /**
     * Swift: host bridge готов (Apple Translation или stub).
     */
    func setHostTranslationAvailable(available: Bool) 
    
    /**
     * Включить/выключить sync-перевод и задать target (`ru`|`en`|`es`).
     */
    func setLiveTranslation(enabled: Bool, targetCode: String)  -> String
    
    /**
     * Выбрать генератор post-call артефактов; неизвестные значения используют builtin.
     */
    func setLlmConfig(engineCode: String, modelId: String, baseUrl: String)
    
    /**
     * Primary язык распознавания (`ru` | `en` | `es`). Не включает перевод.
     */
    func setSessionLanguage(primaryCode: String)  -> String
    
    /**
     * Backend: `off` | `auto` | `stub` | `apple` | `backend` | `local_llm`.
     * `base_url` используется для `backend` / `auto→backend`.
     */
    func setTranslationBackend(kindCode: String, baseUrl: String)  -> String
    
    /**
     * Старт demo captions (scripted, без аудио).
     */
    func startDemo() 
    
    /**
     * Recording + live STT (Whisper если модель есть и feature включён, иначе Mock).
     */
    func startRecording(sessionId: String)  -> String
    
    func state()  -> String
    
    func stop() 
    
    func stopRecording() 
    
    /**
     * `idle` | `mock` | `whisper`.
     */
    func sttBackend()  -> String
    
    func submitBackendJob(meetingId: String, kindCode: String)  -> FfiBackendJob
    
    /**
     * Пустая строка = OK.
     */
    func testApiConnection()  -> String
    
    func translationBackend()  -> String
    
    func upsertGlossaryTerm(term: FfiGlossaryTerm)  -> String
    
    /**
     * Создать или обновить ручную метку спикера; пустой id генерируется здесь.
     */
    func upsertSpeaker(meetingId: String, id: String, displayName: String, sortIndex: Int64)  -> String
    
    /**
     * Абсолютный путь к найденной ggml-модели или пустая строка.
     */
