public struct FfiConverterTypeMeetingCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = MeetingCore

    public static func lift(_ handle: UInt64) throws -> MeetingCore {
        return MeetingCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: MeetingCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MeetingCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: MeetingCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


